def sellar_estatus_desde(apps, schema_editor):
    PreOrden = apps.get_model("produccion", "PreOrdenProduccion")
    PreOrden.objects.filter(estatus_desde__isnull=True).update(estatus_desde=models.F("created_at"))
    # Las pre-órdenes que ya existían arrancan su historial con "creada".
    Evento = apps.get_model("produccion", "PreOrdenEvento")
    for pre in PreOrden.objects.all().only("id", "created_at"):
        ev = Evento.objects.create(pre_orden_id=pre.pk, evento="creada", descripcion="Creada antes del historial.")
        Evento.objects.filter(pk=ev.pk).update(fecha=pre.created_at)


